def main():
    OUT.mkdir(parents=True,exist_ok=True)
    for name,value in [('report.html',HTML),('report.css',CSS),('report.js',JS)]:
        (OUT/name).write_text(value,encoding='utf-8')
    print(OUT/'report.html')
if __name__=='__main__':main()
